//==========================================
// ALGORITHMS MODULE (sorting, searching, timing)    HOA 6, 7, 8, 11, 14
//
// Every algorithm is a template, so the same code sorts numbers, game pointers or text.
// A "Less" argument is a function (or functor) that answers "does a come before b?".
// It must be STRICT: less(a, a) is false. Equal items must not "come before" each other.
//
// SortStats counts what the algorithm really did, so the benchmark can show comparisons and
// moves next to the measured time:
//   comparisons = how many times two items were compared
//   moves       = how many times an item was swapped, shifted or copied
//
// Stable = equal items keep their original order.
//   stable    : bubble, insertion, merge
//   not stable: selection, shell, quick
//==========================================

struct SortStats {
    long long comparisons = 0;
    long long moves = 0;
};

// the six sorting algorithms of the course, in the order they are taught
enum SortAlgo {
    ALGO_BUBBLE = 0,
    ALGO_SELECTION,
    ALGO_INSERTION,
    ALGO_SHELL,
    ALGO_MERGE,
    ALGO_QUICK,
    ALGO_COUNT
};

//--- sortAlgoName ---------------------------------------------------------------------------------
// What    : The display name of a sorting algorithm.
// Returns : the name
// Used by : doLab (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
const char* sortAlgoName(SortAlgo algo) {
    switch (algo) {
        case ALGO_BUBBLE:    return "Bubble Sort";
        case ALGO_SELECTION: return "Selection Sort";
        case ALGO_INSERTION: return "Insertion Sort";
        case ALGO_SHELL:     return "Shell Sort";
        case ALGO_MERGE:     return "Merge Sort";
        case ALGO_QUICK:     return "Quick Sort";
        default:             return "?";
    }
}

//--- sortAlgoAverage ------------------------------------------------------------------------------
// What    : The average running time of an algorithm in Big-O, for the benchmark table.
// Returns : text such as O(n log n)
// Used by : doLab (screens.h)
//--------------------------------------------------------------------------------------------------
const char* sortAlgoAverage(SortAlgo algo) {
    switch (algo) {
        case ALGO_BUBBLE:
        case ALGO_SELECTION:
        case ALGO_INSERTION: return "O(n^2)";
        case ALGO_SHELL:     return "O(n^1.5)";
        default:             return "O(n log n)";
    }
}

//--- sortAlgoWorst --------------------------------------------------------------------------------
// What    : The worst case running time of an algorithm in Big-O.
// Returns : text such as O(n^2)
// Used by : doLab (screens.h)
//--------------------------------------------------------------------------------------------------
const char* sortAlgoWorst(SortAlgo algo) {
    switch (algo) {
        case ALGO_BUBBLE:
        case ALGO_SELECTION:
        case ALGO_INSERTION:
        case ALGO_QUICK:     return "O(n^2)";
        case ALGO_SHELL:     return "O(n^2)";
        default:             return "O(n log n)";
    }
}

//--- sortAlgoBest ---------------------------------------------------------------------------------
// What    : The best case running time of an algorithm in Big-O.
// Returns : text such as O(n)
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
const char* sortAlgoBest(SortAlgo algo) {
    switch (algo) {
        case ALGO_BUBBLE:
        case ALGO_INSERTION: return "O(n)";
        case ALGO_SELECTION: return "O(n^2)";
        case ALGO_SHELL:     return "O(n log n)";
        default:             return "O(n log n)";
    }
}

//--- sortAlgoIsStable -----------------------------------------------------------------------------
// What    : Tells if equal items keep their original order with this algorithm (bubble, insertion
//           and merge do).
// Returns : true when stable
// Used by : doLab (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
bool sortAlgoIsStable(SortAlgo algo) {
    return algo == ALGO_BUBBLE || algo == ALGO_INSERTION || algo == ALGO_MERGE;
}

// the quadratic algorithms need minutes for very large arrays, the benchmark skips them above this size
const int QUADRATIC_SORT_LIMIT = 30000;

//--- sortAlgoIsQuadratic --------------------------------------------------------------------------
// What    : Tells if the algorithm takes O(n^2) time on average, so the benchmark can skip it for
//           huge inputs.
// Returns : true for bubble, selection and insertion
// Used by : benchmarkSort (benchmark.h)
//--------------------------------------------------------------------------------------------------
bool sortAlgoIsQuadratic(SortAlgo algo) {
    return algo == ALGO_BUBBLE || algo == ALGO_SELECTION || algo == ALGO_INSERTION;
}

//==========================
// Stopwatch (std::chrono)
//==========================
class Stopwatch {
private:
    std::chrono::steady_clock::time_point startTime;

public:
//--- Stopwatch::Stopwatch -------------------------------------------------------------------------
// What    : Starts the stopwatch (std::chrono::steady_clock).
// Used by : benchmarkSort (benchmark.h), doLab (screens.h)
//--------------------------------------------------------------------------------------------------
    Stopwatch() : startTime(std::chrono::steady_clock::now()) {}

//--- Stopwatch::restart ---------------------------------------------------------------------------
// What    : Starts counting again from zero.
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    void restart() { startTime = std::chrono::steady_clock::now(); }

    // milliseconds since the stopwatch was created or restarted
//--- Stopwatch::elapsedMs -------------------------------------------------------------------------
// What    : Time since the start or the last restart.
// Returns : milliseconds as a double
// Used by : benchmarkSort (benchmark.h), doLab (screens.h)
//--------------------------------------------------------------------------------------------------
    double elapsedMs() const {
        return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - startTime).count();
    }
};

//==========================
// helpers that also count (used by every sort)
//==========================
//--- countedLess ----------------------------------------------------------------------------------
// What    : Calls the comparison function and counts the call in the statistics.
// Returns : the result of less(a, b)
// Used by : bubbleSort, insertionSort, mergeSortRange, quickSortRange, selectionSort, shellSort
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
bool countedLess(const T& a, const T& b, Less less, SortStats* st) {
    if (st != nullptr) st->comparisons++;
    return less(a, b);
}

//--- swapItems ------------------------------------------------------------------------------------
// What    : Swaps two items and counts one move in the statistics.
// Used by : bubbleSort, quickSortRange, selectionSort
//--------------------------------------------------------------------------------------------------
template <typename T>
void swapItems(T& a, T& b, SortStats* st) {
    T temp = a;
    a = b;
    b = temp;
    if (st != nullptr) st->moves++;
}

//--- isSorted -------------------------------------------------------------------------------------
// What    : Checks that an array is in order under the given comparison. Used to verify every
//           benchmark result.
// Returns : true when sorted
// Used by : benchmarkSort (benchmark.h)
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
bool isSorted(const T* a, int n, Less less) {
    for (int i = 1; i < n; i++) {
        if (less(a[i], a[i - 1])) return false;
    }
    return true;
}

//==========================
// 1. Bubble sort: compare neighbours and swap them, the biggest item "bubbles" to the end.
//    A pass without any swap means the array is sorted, so a sorted array costs only O(n).
//==========================
//--- bubbleSort -----------------------------------------------------------------------------------
// What    : Bubble sort: compare neighbours and swap them so the biggest item bubbles to the end.
//           Stops early after a pass without swaps, so sorted input costs only O(n).
// Used by : sortWith
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
void bubbleSort(T* a, int n, Less less, SortStats* st = nullptr) {
    for (int pass = 0; pass < n - 1; pass++) {
        bool swapped = false;
        for (int j = 0; j < n - 1 - pass; j++) {
            if (countedLess(a[j + 1], a[j], less, st)) {
                swapItems(a[j], a[j + 1], st);
                swapped = true;
            }
        }
        if (!swapped) return;
    }
}

//==========================
// 2. Selection sort: find the smallest of the unsorted part and put it in front.
//    Always O(n^2) comparisons, but at most n - 1 swaps.
//==========================
//--- selectionSort --------------------------------------------------------------------------------
// What    : Selection sort: find the smallest item of the unsorted part and put it first. Always
//           O(n^2) comparisons but at most n-1 swaps.
// Used by : sortWith
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
void selectionSort(T* a, int n, Less less, SortStats* st = nullptr) {
    for (int i = 0; i < n - 1; i++) {
        int smallest = i;
        for (int j = i + 1; j < n; j++) {
            if (countedLess(a[j], a[smallest], less, st)) smallest = j;
        }
        if (smallest != i) swapItems(a[i], a[smallest], st);
    }
}

//==========================
// 3. Insertion sort: take the next item and slide it left until it is in place.
//    Fast on nearly sorted data, O(n) when it is already sorted.
//==========================
//--- insertionSort --------------------------------------------------------------------------------
// What    : Insertion sort: take the next item and slide it left until it is in place. Fast on
//           nearly sorted data.
// Used by : doShowcase (screens.h), sortWith
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
void insertionSort(T* a, int n, Less less, SortStats* st = nullptr) {
    for (int i = 1; i < n; i++) {
        T key = a[i];
        int j = i - 1;
        while (j >= 0 && countedLess(key, a[j], less, st)) {
            a[j + 1] = a[j];
            if (st != nullptr) st->moves++;
            j--;
        }
        if (j + 1 != i) {
            a[j + 1] = key;
            if (st != nullptr) st->moves++;
        }
    }
}

//==========================
// 4. Shell sort: insertion sort on items that are "gap" places apart, the gap shrinks to 1.
//    The far items travel quickly, so the last pass (gap 1) has little left to do.
//==========================
//--- shellSort ------------------------------------------------------------------------------------
// What    : Shell sort: insertion sort on items that are "gap" places apart, with the gap halved
//           until it is 1.
// Used by : sortWith
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
void shellSort(T* a, int n, Less less, SortStats* st = nullptr) {
    for (int gap = n / 2; gap > 0; gap /= 2) {
        for (int i = gap; i < n; i++) {
            T key = a[i];
            int j = i;
            while (j >= gap && countedLess(key, a[j - gap], less, st)) {
                a[j] = a[j - gap];
                if (st != nullptr) st->moves++;
                j -= gap;
            }
            if (j != i) {
                a[j] = key;
                if (st != nullptr) st->moves++;
            }
        }
    }
}

//==========================
// 5. Merge sort: split in two halves, sort each, then merge them with a temporary array.
//    Always O(n log n), stable, needs O(n) extra memory.
//==========================
//--- mergeSortRange -------------------------------------------------------------------------------
// What    : The recursive part of merge sort: sort both halves, then merge them through a temporary
//           array. Takes from the right half only when strictly smaller, so it is stable.
// Used by : mergeSort
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
void mergeSortRange(T* a, T* temp, int lo, int hi, Less less, SortStats* st) {
    if (hi - lo < 2) return;                       // 0 or 1 item is already sorted
    int mid = lo + (hi - lo) / 2;
    mergeSortRange(a, temp, lo, mid, less, st);
    mergeSortRange(a, temp, mid, hi, less, st);

    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        // take from the right half only when it is strictly smaller, this keeps the sort stable
        if (countedLess(a[j], a[i], less, st)) temp[k++] = a[j++];
        else temp[k++] = a[i++];
        if (st != nullptr) st->moves++;
    }
    while (i < mid) { temp[k++] = a[i++]; if (st != nullptr) st->moves++; }
    while (j < hi)  { temp[k++] = a[j++]; if (st != nullptr) st->moves++; }
    for (k = lo; k < hi; k++) a[k] = temp[k];
}

//--- mergeSort ------------------------------------------------------------------------------------
// What    : Merge sort: always O(n log n), stable, needs O(n) extra memory for the temporary array.
// Used by : doFeatured (screens.h), sortWith
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
void mergeSort(T* a, int n, Less less, SortStats* st = nullptr) {
    if (n < 2) return;
    std::vector<T> temp((size_t)n);
    mergeSortRange(a, temp.data(), 0, n, less, st);
}

//==========================
// 6. Quick sort: pick a pivot, move smaller items to its left and bigger to its right, repeat on both sides.
//    O(n log n) on average. The pivot is the MIDDLE item, so sorted and reversed input is not a bad case.
//    The smaller side is solved by recursion and the bigger side by the loop, so the recursion stays O(log n) deep.
//==========================
//--- quickSortRange -------------------------------------------------------------------------------
// What    : The partition loop of quick sort with the middle item as pivot. It recurses on the
//           smaller side and loops on the bigger side, so the recursion depth stays O(log n).
// Used by : quickSort
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
void quickSortRange(T* a, int lo, int hi, Less less, SortStats* st) {
    while (lo < hi) {
        T pivot = a[lo + (hi - lo) / 2];
        int i = lo, j = hi;
        while (i <= j) {
            while (countedLess(a[i], pivot, less, st)) i++;
            while (countedLess(pivot, a[j], less, st)) j--;
            if (i <= j) {
                if (i != j) swapItems(a[i], a[j], st);
                i++;
                j--;
            }
        }
        // now [lo..j] holds the small items and [i..hi] the big ones
        if (j - lo < hi - i) {
            quickSortRange(a, lo, j, less, st);
            lo = i;
        } else {
            quickSortRange(a, i, hi, less, st);
            hi = j;
        }
    }
}

//--- quickSort ------------------------------------------------------------------------------------
// What    : Quick sort: O(n log n) on average, not stable. The middle pivot makes sorted and
//           reversed input a normal case.
// Used by : sortWith
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
void quickSort(T* a, int n, Less less, SortStats* st = nullptr) {
    if (n < 2) return;
    quickSortRange(a, 0, n - 1, less, st);
}

//==========================
// run the algorithm that was chosen from a menu
//==========================
//--- sortWith -------------------------------------------------------------------------------------
// What    : Runs the algorithm that the user picked from a menu (switch on SortAlgo).
// Used by : benchmarkSort (benchmark.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
void sortWith(SortAlgo algo, T* a, int n, Less less, SortStats* st = nullptr) {
    switch (algo) {
        case ALGO_BUBBLE:    bubbleSort(a, n, less, st); break;
        case ALGO_SELECTION: selectionSort(a, n, less, st); break;
        case ALGO_INSERTION: insertionSort(a, n, less, st); break;
        case ALGO_SHELL:     shellSort(a, n, less, st); break;
        case ALGO_MERGE:     mergeSort(a, n, less, st); break;
        case ALGO_QUICK:     quickSort(a, n, less, st); break;
        default: break;
    }
}

//==========================
// Searching
//==========================
// Linear search: look at every item from the start. Works on any array, O(n).
// returns the index of the first match, or -1
//--- linearSearch ---------------------------------------------------------------------------------
// What    : Linear search: looks at every item from the start. Works on any array, O(n).
// Returns : the index of the first match, or -1
// Used by : benchmarkSearch (benchmark.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
template <typename T>
int linearSearch(const T* a, int n, const T& key, long long* comparisons = nullptr) {
    for (int i = 0; i < n; i++) {
        if (comparisons != nullptr) (*comparisons)++;
        if (a[i] == key) return i;
    }
    return -1;
}

// Binary search: the array MUST be sorted. Look at the middle, then keep the half that can still hold the key. O(log n).
// returns the index of a match, or -1
//--- binarySearch ---------------------------------------------------------------------------------
// What    : Binary search on a SORTED array: look in the middle, then keep the half that can still
//           hold the key. O(log n).
// Returns : the index of a match, or -1
// Used by : benchmarkSearch (benchmark.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
template <typename T, typename Less>
int binarySearch(const T* a, int n, const T& key, Less less, long long* comparisons = nullptr) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (comparisons != nullptr) (*comparisons)++;
        if (less(a[mid], key)) {
            lo = mid + 1;
        } else {
            if (comparisons != nullptr) (*comparisons)++;
            if (less(key, a[mid])) hi = mid - 1;
            else return mid;
        }
    }
    return -1;
}

// Binary search for a boundary: the first index whose item is NOT "before" the wanted spot.
// stillBefore(item) must be true for a prefix of the array and false for the rest.
// lower bound of x : stillBefore = (item < x)         upper bound of x : stillBefore = (item <= x)
// The items from lowerBound up to upperBound are exactly the items equal to x (or inside a price range).
//--- partitionPoint -------------------------------------------------------------------------------
// What    : Binary search for a boundary: the first index whose item is not "before" the wanted
//           spot. Gives lower and upper bounds, for example all games in a price range.
// Returns : the boundary index
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
template <typename T, typename Pred>
int partitionPoint(const T* a, int n, Pred stillBefore, long long* comparisons = nullptr) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (comparisons != nullptr) (*comparisons)++;
        if (stillBefore(a[mid])) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

#endif //STEAM_ALGORITHMS_H
